{"file_path":"src/errors.js","content":"/** The one failure shape the command reports. */
export class ConfError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

/** Joins a parent path and a key the way every message and `keys` line does. */
export function childPath(parent, key) {
  return parent === '' ? key : `${parent}.${key}`
}

/** Appends an array index to a path. */
export function indexPath(parent, index) {
  return `${parent}[${index}]`
}
"}

