{"file_path":"src/parse.js","content":"/**
 * The reader for the configuration document. `parse` turns the text into a
 * tree of tagged nodes, or throws a ConfError naming the first fault.
 */

import { ConfError, childPath, indexPath } from './errors.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const DIGITS = '[0-9]+(?:_[0-9]+)*'
const INTEGER = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`)

/** A table, keyed in insertion order; ordering happens when printing. */
function newTable(explicit) {
  return { kind: 'table', map: new Map(), explicit }
}

function newArrayTable() {
  return { kind: 'arraytable', items: [] }
}

function isCommentStart(ch) {
  return ch === '#' || ch === ';'
}

function isSpace(ch) {
  return ch === ' ' || ch === '\t'
}

/** Splits the document the way the specification asks, dropping the tail. */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

class LineReader {
  constructor(text, line) {
    this.s = text
    this.i = 0
    this.line = line
  }

  fail(reason) {
    throw new ConfError(this.line, reason)
  }

  get done() {
    return this.i >= this.s.length
  }

  peek() {
    return this.i < this.s.length ? this.s[this.i] : ''
  }

  skipSpace() {
    while (!this.done && isSpace(this.s[this.i])) this.i += 1
  }

  /** True once nothing but a comment can remain. */
  atEnd() {
    return this.done || isCommentStart(this.peek())
  }

  /** A bare word or a quoted string, decoded. */
  name() {
    const ch = this.peek()
    if (ch === '"') return this.basicString()
    if (ch === "'") return this.literalString()
    if (ch !== '' && NAME_CHAR.test(ch)) {
      const start = this.i
      while (!this.done && NAME_CHAR.test(this.s[this.i])) this.i += 1
      return this.s.slice(start, this.i)
    }
    this.fail('expected a name')
    return ''
  }

  /** Names joined by dots, with spaces and tabs allowed around each dot. */
  dottedName() {
    const parts = [this.name()]
    for (;;) {
      const mark = this.i
      this.skipSpace()
      if (this.peek() !== '.') {
        this.i = mark
        return parts
      }
      this.i += 1
      this.skipSpace()
      parts.push(this.name())
    }
  }

  basicString() {
    this.i += 1
    let out = ''
    for (;;) {
      if (this.done) this.fail('unterminated string')
      const ch = this.s[this.i]
      if (ch === '"') {
        this.i += 1
        return out
      }
      if (ch === '\\') {
        this.i += 1
        if (this.done) this.fail('unterminated string')
        const esc = this.s[this.i]
        this.i += 1
        if (esc === '"') out += '"'
        else if (esc === '\\') out += '\\'
        else if (esc === 'n') out += '\n'
        else if (esc === 't') out += '\t'
        else if (esc === 'r') out += '\r'
        else if (esc === '0') out += '\0'
        else if (esc === 'u') {
          const hex = this.s.slice(this.i, this.i + 4)
          if (hex.length !== 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) this.fail('invalid escape \\u')
          this.i += 4
          out += String.fromCharCode(parseInt(hex, 16))
        } else this.fail(`invalid escape \\${esc}`)
        continue
      }
      out += ch
      this.i += 1
    }
  }

  literalString() {
    this.i += 1
    const start = this.i
    while (!this.done && this.s[this.i] !== "'") this.i += 1
    if (this.done) this.fail('unterminated string')
    const out = this.s.slice(start, this.i)
    this.i += 1
    return out
  }

  /** One value, which may be a whole array or inline table. */
  value(assign) {
    this.skipSpace()
    const ch = this.peek()
    if (ch === '' || isCommentStart(ch) || ch === ',' || ch === ']' || ch === '}') {
      this.fail('expected a value')
    }
    if (ch === '"') return { kind: 'string', value: this.basicString() }
    if (ch === "'") return { kind: 'string', value: this.literalString() }
    if (ch === '[') return this.array(assign)
    if (ch === '{') return this.inlineTable(assign)

    const start = this.i
    while (!this.done) {
      const c = this.s[this.i]
      if (isSpace(c) || c === ',' || c === ']' || c === '}') break
      this.i += 1
    }
    const text = this.s.slice(start, this.i)
    if (text === 'true') return { kind: 'boolean', value: true }
    if (text === 'false') return { kind: 'boolean', value: false }
    const plain = text.replace(/_/g, '')
    if (INTEGER.test(text)) return { kind: 'integer', value: Number(plain) }
    if (FLOAT.test(text) && /[.eE]/.test(text)) return { kind: 'float', value: Number(plain) }
    this.fail(`invalid value ${text}`)
    return null
  }

  array(assign) {
    this.i += 1
    const node = { kind: 'array', items: [] }
    for (;;) {
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.peek() === ']') {
        this.i += 1
        return node
      }
      node.items.push(this.value(assign))
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated array')
      const ch = this.peek()
      if (ch === ',') {
        this.i += 1
        continue
      }
      if (ch === ']') {
        this.i += 1
        return node
      }
      this.fail('unterminated array')
    }
  }

  inlineTable(assign) {
    this.i += 1
    const node = newTable(false)
    this.skipSpace()
    if (this.atEnd()) this.fail('unterminated inline table')
    if (this.peek() === '}') {
      this.i += 1
      return node
    }
    for (;;) {
      this.skipSpace()
      const parts = this.dottedName()
      this.skipSpace()
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.i += 1
      const value = this.value(assign)
      assign(node, parts, value, this.line)
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated inline table')
      const ch = this.peek()
      if (ch === ',') {
        this.i += 1
        continue
      }
      if (ch === '}') {
        this.i += 1
        return node
      }
      this.fail('unterminated inline table')
    }
  }
}

/**
 * Reads the whole document. The tree it returns is a table node whose members
 * are the nodes named at the top level.
 */
export function parse(text) {
  const root = newTable(true)
  const paths = new Map([[root, '']])
  let current = root

  /** Steps through the names a dot walks, making the tables it needs. */
  const walk = (table, parts, line) => {
    let node = table
    for (const part of parts) {
      let next = node.map.get(part)
      if (next === undefined) {
        next = newTable(false)
        paths.set(next, childPath(paths.get(node), part))
        node.map.set(part, next)
      }
      if (next.kind === 'arraytable') {
        const last = next.items[next.items.length - 1]
        if (last === undefined) {
          throw new ConfError(line, `${childPath(paths.get(node), part)} is not a table`)
        }
        next = last
      } else if (next.kind !== 'table') {
        throw new ConfError(line, `${childPath(paths.get(node), part)} is not a table`)
      }
      node = next
    }
    return node
  }

  const assign = (table, parts, value, line) => {
    const holder = walk(table, parts.slice(0, -1), line)
    const key = parts[parts.length - 1]
    if (holder.map.has(key)) {
      throw new ConfError(line, `key ${childPath(paths.get(holder), key)} is defined twice`)
    }
    holder.map.set(key, value)
    label(value, childPath(paths.get(holder), key))
  }

  /** Records the path of a value and of everything it carries. */
  const label = (node, path) => {
    paths.set(node, path)
    if (node.kind === 'table') {
      for (const [key, child] of node.map) label(child, childPath(path, key))
    } else if (node.kind === 'array' || node.kind === 'arraytable') {
      node.items.forEach((item, index) => label(item, indexPath(path, index)))
    }
  }

  const lines = splitLines(text)
  for (let n = 0; n < lines.length; n += 1) {
    const reader = new LineReader(lines[n], n + 1)
    reader.skipSpace()
    if (reader.atEnd()) continue

    if (reader.peek() === '[') {
      reader.i += 1
      const isArray = reader.peek() === '['
      if (isArray) reader.i += 1
      reader.skipSpace()
      const parts = reader.dottedName()
      reader.skipSpace()
      if (isArray) {
        if (reader.peek() !== ']' || reader.s[reader.i + 1] !== ']') {
          reader.fail('unterminated table header')
        }
        reader.i += 2
      } else {
        if (reader.peek() !== ']') reader.fail('unterminated table header')
        reader.i += 1
      }
      reader.skipSpace()
      if (!reader.atEnd()) reader.fail('trailing text after a table header')

      const holder = walk(root, parts.slice(0, -1), n + 1)
      const key = parts[parts.length - 1]
      const path = childPath(paths.get(holder), key)
      const held = holder.map.get(key)
      if (isArray) {
        let target = held
        if (target === undefined) {
          target = newArrayTable()
          paths.set(target, path)
          holder.map.set(key, target)
        } else if (target.kind !== 'arraytable') {
          throw new ConfError(n + 1, `${path} is not an array of tables`)
        }
        const fresh = newTable(true)
        paths.set(fresh, indexPath(path, target.items.length))
        target.items.push(fresh)
        current = fresh
      } else {
        if (held === undefined) {
          const fresh = newTable(true)
          paths.set(fresh, path)
          holder.map.set(key, fresh)
          current = fresh
        } else if (held.kind !== 'table') {
          throw new ConfError(n + 1, `${path} is not a table`)
        } else if (held.explicit) {
          throw new ConfError(n + 1, `table ${path} is defined twice`)
        } else {
          held.explicit = true
          current = held
        }
      }
      continue
    }

    const parts = reader.dottedName()
    reader.skipSpace()
    if (reader.peek() !== '=') reader.fail('expected key = value')
    reader.i += 1
    const value = reader.value(assign)
    reader.skipSpace()
    if (!reader.atEnd()) reader.fail('trailing text after a value')
    assign(current, parts, value, n + 1)
  }

  return root
}
"}

