import { childPath, indexPath } from './errors.js'

/** Compares two keys by code point, which is what the ordering asks for. */
export function compareKeys(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const shared = Math.min(left.length, right.length)
  for (let i = 0; i < shared; i += 1) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  return left.length - right.length
}

function sortedEntries(table) {
  return [...table.map.entries()].sort((a, b) => compareKeys(a[0], b[0]))
}

function render(node, indent) {
  const pad = ' '.repeat(indent)
  const inner = ' '.repeat(indent + 2)
  if (node.kind === 'table') {
    const entries = sortedEntries(node)
    if (entries.length === 0) return '{}'
    const body = entries
      .map(([key, child]) => `${inner}${JSON.stringify(key)}: ${render(child, indent + 2)}`)
      .join(',\n')
    return `{\n${body}\n${pad}}`
  }
  if (node.kind === 'array' || node.kind === 'arraytable') {
    if (node.items.length === 0) return '[]'
    const body = node.items.map((item) => `${inner}${render(item, indent + 2)}`).join(',\n')
    return `[\n${body}\n${pad}]`
  }
  return JSON.stringify(node.value)
}

/** The document as canonical JSON, with its trailing newline. */
export function toJson(root) {
  return `${render(root, 0)}\n`
}

function typeName(node) {
  if (node.kind === 'arraytable') return 'array'
  return node.kind
}

/** One line per node below the root, depth first. */
export function toKeys(root) {
  const out = []
  const visit = (node, path) => {
    if (node.kind === 'table') {
      for (const [key, child] of sortedEntries(node)) {
        const here = childPath(path, key)
        out.push(`${here} ${typeName(child)}\n`)
        visit(child, here)
      }
    } else if (node.kind === 'array' || node.kind === 'arraytable') {
      node.items.forEach((item, index) => {
        const here = indexPath(path, index)
        out.push(`${here} ${typeName(item)}\n`)
        visit(item, here)
      })
    }
  }
  visit(root, '')
  return out.join('')
}
"}

